// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class GH6400WalPurgeSequenceReviewTest {

	@TempDir
	Path directory;

	@Test
	void purgeStartsACompleteWalSequenceWithoutOldValues() throws Exception {
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(directory)
				.storeUuid("purge-sequence-review")
				.syncPolicy(ValueStoreWalConfig.SyncPolicy.COMMIT)
				.build();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			long before = wal.logMint(41, ValueStoreWalValueKind.LITERAL, "before clear", "", "", 0);
			wal.awaitDurable(before);
			wal.purgeAllSegments();
			long after = wal.logMint(1, ValueStoreWalValueKind.LITERAL, "after clear", "", "", 0);
			wal.awaitDurable(after);
		}

		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			ValueStoreWalReader.Summary summary = reader.summarize();
			assertThat(summary.complete()).as("the first segment after a complete purge starts a new sequence")
					.isTrue();
			assertThat(summary.maxId()).isEqualTo(1);
			assertThat(summary.contiguousId()).isEqualTo(1);
		}
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			var records = reader.scan().records();
			assertThat(records).extracting(ValueStoreWalRecord::id).containsExactly(1);
			assertThat(records).extracting(ValueStoreWalRecord::lexical).containsExactly("after clear");
		}
	}
}
